import { useState, useRef, useCallback } from "react";
import { store } from "../../store";

// ── Draggable / hideable floating overlay primitive ───────────────────────
// Every floating tool in the viewer (tuner, metronome, recorder indicator,
// open/drive/imslp actions, page navigator) wraps itself in this so the
// user can drag any of them to a new spot or hide them — like the
// repositionable floating controls in the IMSLP app — without each tool
// re-implementing drag/persist logic.
//
// `editMode` (lifted to ScoreViewer, toggled by one global button) gates
// behavior: off, the child's own onClick works normally; on, dragging is
// enabled and taps are swallowed so repositioning never also triggers
// Play/Stop or similar.
export default function FloatingButton({ id, defaultPos, editMode, children }) {
  const [pos, setPos]       = useState(() => store.get(`fabpos-${id}`, defaultPos));
  const [hidden, setHidden] = useState(() => store.get(`fabhidden-${id}`, false));
  const dragRef = useRef(null); // { startX, startY, origPos }

  const onDown = useCallback((e) => {
    if (!editMode) return;
    e.preventDefault();
    e.stopPropagation();
    e.currentTarget.setPointerCapture?.(e.pointerId);
    dragRef.current = { startX: e.clientX, startY: e.clientY, origPos: pos };
  }, [editMode, pos]);

  const onMove = useCallback((e) => {
    if (!dragRef.current) return;
    e.preventDefault();
    const { startX, startY, origPos } = dragRef.current;
    const dx = e.clientX - startX, dy = e.clientY - startY;
    setPos(prev => {
      const next = { ...origPos };
      if (next.left != null) next.left = Math.max(0, origPos.left + dx);
      if (next.right != null) next.right = Math.max(0, origPos.right - dx);
      if (next.top != null) next.top = Math.max(0, origPos.top + dy);
      if (next.bottom != null) next.bottom = Math.max(0, origPos.bottom - dy);
      return next;
    });
  }, []);

  const onUp = useCallback(() => {
    if (!dragRef.current) return;
    dragRef.current = null;
    setPos(p => { store.set(`fabpos-${id}`, p); return p; });
  }, [id]);

  const toggleHidden = useCallback((e) => {
    e.stopPropagation();
    setHidden(h => { const next = !h; store.set(`fabhidden-${id}`, next); return next; });
  }, [id]);

  if (hidden && !editMode) return null;

  return (
    <div
      onPointerDown={onDown}
      onPointerMove={onMove}
      onPointerUp={onUp}
      onPointerCancel={onUp}
      style={{
        position: "absolute",
        ...pos,
        zIndex: editMode ? 30 : 10,
        touchAction: editMode ? "none" : "auto",
        cursor: editMode ? "grab" : "default",
        opacity: hidden ? 0.35 : 1,
        outline: editMode ? "2px dashed rgba(143,188,143,0.6)" : "none",
        outlineOffset: 4,
        borderRadius: 14,
      }}
    >
      {children}
      {editMode && (
        <button
          onPointerDown={e => e.stopPropagation()}
          onClick={toggleHidden}
          title={hidden ? "Mostrar" : "Ocultar"}
          style={{
            position: "absolute", top: -8, right: -8, width: 20, height: 20, borderRadius: "50%",
            background: hidden ? "#4a7c59" : "#c0504d", color: "#fff", border: "1px solid rgba(255,255,255,0.4)",
            fontSize: 11, lineHeight: 1, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center",
            zIndex: 31,
          }}
        >
          {hidden ? "+" : "×"}
        </button>
      )}
    </div>
  );
}
