import * as pdfjsLib from "pdfjs-dist/legacy/build/pdf";

let wired = false;

// Local worker bundled by webpack — no CDN, works offline (critical for the
// Capacitor iOS/Android builds, which can't rely on network at runtime).
//
// Explicitly construct the Worker and hand it to pdf.js via `workerPort`
// instead of just setting `workerSrc` and letting pdf.js decide how to load
// it. With only `workerSrc` set, pdf.js's own "is this a real worker or do
// I need a fake one" probe can mis-detect on Safari/iOS and fall back to
// "fake worker" mode (running the worker script on the main thread) — which
// then fails outright with "window.pdfjsWorker.WorkerMessageHandler is
// undefined" because the legacy worker bundle doesn't expose that global in
// a plain <script>/main-thread context, only when actually run as a Worker.
// Constructing the Worker ourselves sidesteps that detection entirely.
export function getPdfjs() {
  if (!wired) {
    const workerUrl = new URL("pdfjs-dist/legacy/build/pdf.worker.min.js", import.meta.url);
    try {
      pdfjsLib.GlobalWorkerOptions.workerPort = new Worker(workerUrl);
    } catch {
      // Extremely old/locked-down environments without Worker support at
      // all — fall back to pdf.js's own loading strategy rather than crash.
      pdfjsLib.GlobalWorkerOptions.workerSrc = workerUrl.toString();
    }
    wired = true;
  }
  return pdfjsLib;
}
